// Generated by `vexsim calibration-routine` for "Example 6-motor full omni". Regenerate it if the robot changes.
// Logs what the robot measures every 10 ms, in vexsim's robot-log format.
#include "vexsim_calibration.hpp"

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <string>
#include <vector>

#include "api.h"

namespace vexsim_calibration {
namespace {

constexpr int MOTOR_COUNT = 6;
constexpr int MOTORS[MOTOR_COUNT] = {1, 2, 3, 4, 5, 6};  // raw (positive) ports

struct Step {
	const char* name;
	int ms;
	int brake;  // 0 coast, 1 brake: how the motors stop when the step is still
	int mv[MOTOR_COUNT];  // raw voltage per motor (0 = stop)
};

const Step STEPS[] = {
	{"settle", 500, 0, {0, 0, 0, 0, 0, 0}},
	{"launch", 500, 0, {7403, 7403, 7403, -7403, -7403, -7403}},
	{"coast", 800, 0, {0, 0, 0, 0, 0, 0}},
	{"reverse", 1000, 0, {-5923, -5923, -5923, 5923, 5923, 5923}},
	{"brake", 500, 1, {0, 0, 0, 0, 0, 0}},
	{"spin", 1000, 0, {-7200, -7200, -7200, -7200, -7200, -7200}},
	{"coast", 800, 0, {0, 0, 0, 0, 0, 0}},
	{"arc", 900, 0, {10263, 10263, 10263, -3063, -3063, -3063}},
	{"coast", 600, 0, {0, 0, 0, 0, 0, 0}},
	{"brake", 400, 1, {0, 0, 0, 0, 0, 0}},
};

const char* const HEADER = "time_ms,battery_mv,battery_ma,m1_cmd_mv,m1_cmd_rpm,m1_brake,m1_deg,m1_rpm,m1_ma,m1_mv,m1_temp,m2_cmd_mv,m2_cmd_rpm,m2_brake,m2_deg,m2_rpm,m2_ma,m2_mv,m2_temp,m3_cmd_mv,m3_cmd_rpm,m3_brake,m3_deg,m3_rpm,m3_ma,m3_mv,m3_temp,m4_cmd_mv,m4_cmd_rpm,m4_brake,m4_deg,m4_rpm,m4_ma,m4_mv,m4_temp,m5_cmd_mv,m5_cmd_rpm,m5_brake,m5_deg,m5_rpm,m5_ma,m5_mv,m5_temp,m6_cmd_mv,m6_cmd_rpm,m6_brake,m6_deg,m6_rpm,m6_ma,m6_mv,m6_temp,imu10_deg,r11_cdeg,r12_cdeg,d13_mm";

std::vector<std::string> g_rows;
bool g_commands_known = false;
int g_cmd_mv[22] = {};
int g_brake[22] = {};
pros::Task* g_task = nullptr;
bool g_logging = false;

void add(std::string& row, const char* format, double value, bool valid = true) {
	row += ',';
	if (!valid || !std::isfinite(value)) return;
	char buf[32];
	std::snprintf(buf, sizeof buf, format, value);
	row += buf;
}

void motor(std::string& row, int port) {
	int32_t mv = pros::c::motor_get_voltage(port);
	add(row, "%.0f", g_cmd_mv[port], g_commands_known);
	row += ',';  // m<p>_cmd_rpm: the routine only uses voltages
	add(row, "%.0f", g_commands_known ? g_brake[port] : pros::c::motor_get_brake_mode(port));
	add(row, "%.2f", pros::c::motor_get_position(port));
	add(row, "%.2f", pros::c::motor_get_actual_velocity(port));
	int32_t ma = pros::c::motor_get_current_draw(port);
	add(row, "%.0f", ma, ma != PROS_ERR);
	add(row, "%.0f", mv, mv != PROS_ERR);
	add(row, "%.1f", pros::c::motor_get_temperature(port));
}

void rotation(std::string& row, int port) {
	int32_t cdeg = pros::c::rotation_get_position(port);
	add(row, "%.0f", cdeg, cdeg != PROS_ERR);
}

void imu(std::string& row, int port) { add(row, "%.4f", pros::c::imu_get_rotation(port)); }

void distance(std::string& row, int port) {
	int32_t mm = pros::c::distance_get(port);
	add(row, "%.0f", mm, mm != PROS_ERR && mm != 9999);
}

void gps(std::string& row, int port) {
	pros::Gps sensor(port);
	pros::gps_position_s_t p = sensor.get_position();
	add(row, "%.4f", p.x);
	add(row, "%.4f", p.y);
	add(row, "%.3f", sensor.get_heading());
	add(row, "%.4f", sensor.get_error());
}

void sample(std::uint32_t elapsed_ms) {
	std::string row = std::to_string(elapsed_ms);
	int32_t battery_mv = pros::c::battery_get_voltage();
	int32_t battery_ma = pros::c::battery_get_current();
	add(row, "%.0f", battery_mv, battery_mv != PROS_ERR);
	add(row, "%.0f", battery_ma, battery_ma != PROS_ERR);
	motor(row, 1);
	motor(row, 2);
	motor(row, 3);
	motor(row, 4);
	motor(row, 5);
	motor(row, 6);
	imu(row, 10);
	rotation(row, 11);
	rotation(row, 12);
	distance(row, 13);
	g_rows.push_back(row);
}

void apply(const Step& step) {
	for (int i = 0; i < MOTOR_COUNT; i++) {
		int port = MOTORS[i];
		auto brake = step.brake ? pros::E_MOTOR_BRAKE_BRAKE : pros::E_MOTOR_BRAKE_COAST;
		pros::c::motor_set_brake_mode(port, brake);
		if (step.mv[i] != 0) {
			pros::c::motor_move_voltage(port, step.mv[i]);
		} else {
			pros::c::motor_brake(port);  // stops with the brake mode
		}
		g_cmd_mv[port] = step.mv[i];
		g_brake[port] = step.brake;
	}
}

}  // namespace

void run() {
	g_logging = false;
	for (int port : MOTORS) {
		pros::c::motor_set_encoder_units(port, pros::E_MOTOR_ENCODER_DEGREES);
		pros::c::motor_set_brake_mode(port, pros::E_MOTOR_BRAKE_COAST);
		pros::c::motor_brake(port);
	}
	pros::c::imu_reset_blocking(10);  // keep the robot still
	pros::c::rotation_set_reversed(11, false);  // log raw readings
	pros::c::rotation_set_reversed(12, false);  // log raw readings
	g_rows.clear();
	g_rows.reserve(710);
	g_commands_known = true;
	std::uint32_t start = pros::millis(), now = start;
	for (const Step& step : STEPS) {
		apply(step);
		for (int t = 0; t < step.ms; t += 10) {
			sample(now - start);
			pros::c::task_delay_until(&now, 10);
		}
	}
	for (int port : MOTORS) {
		pros::c::motor_set_brake_mode(port, pros::E_MOTOR_BRAKE_BRAKE);
		pros::c::motor_brake(port);
	}
	g_commands_known = false;
	save();
}

void start_logging() {
	if (g_logging) return;
	g_rows.clear();
	g_commands_known = false;
	g_logging = true;
	if (g_task == nullptr) {
		g_task = new pros::Task([] {
			std::uint32_t start = pros::millis(), now = start;
			while (true) {
				if (g_logging) sample(now - start);
				pros::c::task_delay_until(&now, 10);
			}
		});
	}
}

int save() {
	g_logging = false;
	int rows = static_cast<int>(g_rows.size());
	FILE* file = pros::c::usd_is_installed() ? std::fopen("/usd/vexsim_log.csv", "w") : nullptr;
	if (file != nullptr) {
		std::fprintf(file, "%s\n", HEADER);
		for (const std::string& row : g_rows) std::fprintf(file, "%s\n", row.c_str());
		std::fclose(file);
		std::printf("vexsim: wrote %d log rows to /usd/vexsim_log.csv\n", rows);
		return rows;
	}
	std::printf("#vexsim-log begin\n%s\n", HEADER);
	for (int i = 0; i < rows; i++) {
		std::printf("%s\n", g_rows[i].c_str());
		if (i % 20 == 19) {  // let the terminal keep up
			std::fflush(stdout);
			pros::delay(2);
		}
	}
	std::printf("#vexsim-log end\n");
	std::fflush(stdout);
	return rows;
}

}  // namespace vexsim_calibration
